"""Pixel Arena level pathing: bots walk a tile map painted in primary colors."""

from heapq import heappop, heappush

Cell = tuple[int, int]  # (row, col)


def find_path(grid: list[str]) -> list[Cell] | None:
    """Cheapest 4-neighbour path from 'S' to 'G', both inclusive.

    '.' floor costs 1 to enter, 'D' door costs 3, '#' is a wall, 'S'/'G' cost 1.
    Return None when G is unreachable.
    """
    start = goal = None
    for row, tiles in enumerate(grid):
        for col, tile in enumerate(tiles):
            if tile == "S":
                start = (row, col)
            elif tile == "G":
                goal = (row, col)
    if start is None or goal is None:
        return None

    costs = {start: 0}
    parents: dict[Cell, Cell] = {}
    pending = [(0, start)]
    while pending:
        cost, cell = heappop(pending)
        if cost != costs[cell]:
            continue
        if cell == goal:
            path = [cell]
            while cell != start:
                cell = parents[cell]
                path.append(cell)
            path.reverse()
            return path

        row, col = cell
        for next_row, next_col in (
            (row - 1, col), (row + 1, col),
            (row, col - 1), (row, col + 1),
        ):
            if not (0 <= next_row < len(grid)
                    and 0 <= next_col < len(grid[next_row])):
                continue
            tile = grid[next_row][next_col]
            if tile not in ".DSG":
                continue
            neighbor = (next_row, next_col)
            next_cost = cost + (3 if tile == "D" else 1)
            if next_cost < costs.get(neighbor, float("inf")):
                costs[neighbor] = next_cost
                parents[neighbor] = cell
                heappush(pending, (next_cost, neighbor))
    return None

